43	// GET /api/org-chart/stream — Server-Sent Events. Pushes agent upsert/remove
44	// events so the org chart stays in sync with ~/.claude/agents/ in real time.
45	// No rateLimit: this is a long-lived connection.
46	router.get('/org-chart/stream', (req, res) => {
47	  res.set({
48	    'Content-Type': 'text/event-stream',
49	    'Cache-Control': 'no-cache, no-transform',
50	    Connection: 'keep-alive',
51	    'X-Accel-Buffering': 'no',
52	  });
53	  res.flushHeaders?.();
54	
55	  const send = (type, payload) => {
56	    res.write(`event: ${type}\n`);
57	    res.write(`data: ${JSON.stringify(payload)}\n\n`);
58	  };
59	
60	  send('ready', { ts: Date.now() });
61	
62	  const onUpsert = (p) => send('agent:upsert', p);
63	  const onRemove = (p) => send('agent:remove', p);
64	  const onTaxonomy = (p) => send('taxonomy:update', p);
65	
66	  // Phase A — task lifecycle events. Frontend uses these to flip the load
67	  // dot 🟢→🟡→🔴 in real time without polling /api/org-chart.
68	  // Payload shape: { id, agentId, status, ... } (see src/lib/tasks.js).
69	  const onTask = (eventName) => (p) => send(eventName, p);
70	  const onTaskCreated   = onTask('task:created');
71	  const onTaskStarted   = onTask('task:started');
72	  const onTaskCompleted = onTask('task:completed');
73	  const onTaskFailed    = onTask('task:failed');
74	  const onTaskCancelled = onTask('task:cancelled');
75	
76	  agentSync.events.on('agent:upsert', onUpsert);
77	  agentSync.events.on('agent:remove', onRemove);
78	  agentSync.events.on('taxonomy:update', onTaxonomy);
79	  agentSync.events.on('task:created',   onTaskCreated);
80	  agentSync.events.on('task:started',   onTaskStarted);
81	  agentSync.events.on('task:completed', onTaskCompleted);
82	  agentSync.events.on('task:failed',    onTaskFailed);
83	  agentSync.events.on('task:cancelled', onTaskCancelled);
84	
85	  const heartbeat = setInterval(() => {
86	    try { res.write(': keepalive\n\n'); } catch {}
87	  }, 25000);
88	
89	  const cleanup = () => {
90	    clearInterval(heartbeat);
91	    agentSync.events.off('agent:upsert', onUpsert);
92	    agentSync.events.off('agent:remove', onRemove);
93	    agentSync.events.off('taxonomy:update', onTaxonomy);
94	    agentSync.events.off('task:created',   onTaskCreated);
95	    agentSync.events.off('task:started',   onTaskStarted);
96	    agentSync.events.off('task:completed', onTaskCompleted);
97	    agentSync.events.off('task:failed',    onTaskFailed);
98	    agentSync.events.off('task:cancelled', onTaskCancelled);
99	  };
100	  req.on('close', cleanup);
101	  req.on('end', cleanup);
102	});
