115	// POST /api/org-chart/positions — body: { positions: [{ nodeId, x, y }, ...] }
116	// Persists drag positions. Idempotent upsert per nodeId.
117	router.post('/org-chart/positions', rateLimit('write'), (req, res) => {
118	  try {
119	    const positions = Array.isArray(req.body?.positions) ? req.body.positions : [];
120	    if (positions.length === 0) {
121	      return res.status(400).json({ error: 'positions array required' });
122	    }
123	    if (positions.length > 200) {
124	      return res.status(400).json({ error: 'max 200 positions per request' });
125	    }
126	    const saved = db.saveNodePositions(positions);
127	    // Broadcast a taxonomy:update so other tabs reload — reuses the existing
128	    // org-chart SSE pipe instead of adding a new event type.
129	    try { agentSync.events.emit('taxonomy:update', { ts: Date.now(), reason: 'positions' }); } catch {}
130	    res.json({ ok: true, saved });
131	  } catch (err) {
132	    res.status(400).json({ error: err.message });
133	  }
134	});
