179	// Body: { label?, description?, cardLabel?, cardEmoji?, color?, icon?, order?, displayMode?, status?, lead?, memberCount? }
180	// Mutates ~/.claude/org/departments.json sub-dept entry, bumps version,
181	// emits taxonomy:update so all open clients refetch.
182	router.patch('/departments/:deptId/subdepartment/:subId', rateLimit('write'), (req, res) => {
