184	    const { deptId, subId } = req.params;
185	    const patch = req.body || {};
186	    const result = org.updateSubDepartment(deptId, subId, patch);
187	    try {
188	      agentSync.events.emit('taxonomy:update', {
189	        ts: Date.now(),
190	        reason: 'subdepartment:update',
191	        deptId, subId,
192	      });
193	    } catch {}
194	    res.json({ ok: true, ...result });
195	  } catch (err) {
196	    const status = /not found/i.test(err.message) ? 404
197	      : /no valid fields/i.test(err.message) ? 400
198	      : 500;
199	    res.status(status).json({ error: err.message });
200	  }
201	});
