782	    const tiers = policy.tiers || {};
783	    const cutoff = new Date(Date.now() - 30 * 24 * 3600 * 1000).toISOString();
784	    const runs = db.getRecentAgentRuns(30 * 24);
785	
786	    // Build per-tier cost rollup
787	    const summary = {};
788	    const violations = [];
789	    for (const [tierKey, def] of Object.entries(tiers)) {
790	      summary[tierKey] = {
791	        model: def.shortName,
792	        agents: def.agents || [],
793	        runs: 0,
794	        estTokens: 0,
795	        estCostUsd: 0,
796	        budgetUsd: def.monthlyBudgetUsd || 0,
797	      };
798	    }
799	
800	    for (const r of runs) {
801	      const md = r.metadata || {};
802	      // Find which tier this agent belongs to
803	      const tierKey = Object.entries(tiers)
804	        .find(([, def]) => Array.isArray(def.agents) && def.agents.includes(r.agentName))?.[0];
805	      if (tierKey && summary[tierKey]) {
