824	    }
825	
826	    const totalEstCost = Object.values(summary).reduce((acc, t) => acc + t.estCostUsd, 0);
827	    const totalBudget = policy.totalMonthlyBudgetUsd || 0;
828	
829	    res.json({
830	      windowHours: 30 * 24,
831	      cutoff,
832	      enforcementMode: policy.enforcementMode || 'advisory',
833	      tiers: summary,
834	      total: {
835	        estCostUsd: Math.round(totalEstCost * 100) / 100,
836	        budgetUsd: totalBudget,
837	        burnPct: totalBudget > 0 ? Math.round((totalEstCost / totalBudget) * 100) : null,
838	      },
839	      violations: violations.slice(-50),
840	      violationCount: violations.length,
841	    });
